    await this.session.settled();
    const due = this.dueBy();
    const lines = [['name', 'grade', 'retired-from', 'due-total']];
    for (const p of this.people()) {
      lines.push([p.name, this.gradeToday(p), p.retiredFrom ?? '', due.get(p.id) ?? 'n/a']);
    }
    this.downloadCsv('people.csv', lines);
  }

  /**
   * Downloads the people of the sheet's whole tree as a CSV file: this sheet's people first, in list order, as the
   * screen shows them, then the other sheets' people, sheets by id, as the store holds them.
   */
  protected async exportTree(): Promise<void> {
    await this.session.settled();
    const id = this.session.sheetId();
    if (!id) return;
    const due = this.dueBy();
    const lines = [['sheet', 'name', 'grade', 'due-total']];
    for (const p of this.people()) {
      lines.push([id, p.name, this.gradeToday(p), due.get(p.id) ?? 'n/a']);
    }
    const others = await firstValueFrom(
      this.http.get<TreePerson[]>(`/api/sheets/${encodeURIComponent(id)}/tree/people`),
    );
    for (const o of others) {
      lines.push([o.sheet, o.name, o.grade ?? '', o.dueTotal ?? 'n/a']);
    }
    this.downloadCsv('tree.csv', lines);
  }

  /**
   * Downloads every claim as a CSV file: people in list order, retired ones included, each person's claims
   * oldest first, with the figures as the claims list shows them.
   */
  protected async exportClaims(): Promise<void> {
    await this.session.settled();
    const rates = this.rates.byClaim();
    const floor = this.settings.floor();
    const late = this.settings.lateness();
    const periods = this.periods.list();
    const claimsBy = this.claimsBy();
    const lines = [['person', 'number', 'date', 'amount', 'due', 'status', 'period']];
    for (const p of this.people()) {
      for (const c of [...(claimsBy.get(p.id) ?? [])].reverse()) {
        const due = dueOf(c, rates(c).get(gradeOn(p.grades, c.date)) ?? [], floor, late, graceOf(c, p.grades, late));
        const period = periodOn(periods, c.dueBy)?.name ?? '';
        lines.push([p.name, c.number ?? '', c.date, c.amount, due ?? 'n/a', c.status, period]);
      }
    }
    this.downloadCsv('claims.csv', lines);
  }

  /**
   * Downloads each person's figures for each period as a CSV file: people in list order, retired ones included, periods
   * in the order they were added, with the due-total and carried figure as the person's row shows them.
   */
  protected async exportPeriods(): Promise<void> {
    await this.session.settled();
    const periods = [...this.periods.list()].sort((a, b) => a.id - b.id);
    const dueBy = this.periodDueBy();
    const carriedBy = this.periodCarriedBy();
    const lines = [['person', 'period', 'figure', 'carried']];
    for (const p of this.people()) {
      for (const pd of periods) {
        lines.push([
          p.name,
          pd.name,
          dueBy.get(p.id)?.get(pd.id) ?? '0.00',
          carriedBy.get(p.id)?.get(pd.id) ?? '0.00',
        ]);
      }
    }
    this.downloadCsv('periods.csv', lines);
  }

  /**
   * Downloads the person's statement as a CSV file: each claim of theirs bound by their last statement, oldest
   * first, with the bound figure as the claim shows it.
   */
  protected async exportStatement(p: Person): Promise<void> {
    await this.session.settled();
    const rates = this.rates.byClaim();
    const floor = this.settings.floor();
    const late = this.settings.lateness();
    const lines = [['number', 'date', 'amount', 'figure', 'status']];
    for (const c of [...(this.claimsBy().get(p.id) ?? [])].reverse()) {
      if (!isBound(c)) continue;
      const figure = dueOf(c, rates(c).get(gradeOn(p.grades, c.date)) ?? [], floor, late, graceOf(c, p.grades, late));
      lines.push([c.number ?? '', c.date, c.amount, figure ?? 'n/a', c.status]);
    }
    this.downloadCsv(`statement-${p.name}.csv`, lines);
  }

  private downloadCsv(fileName: string, lines: string[][]): void {
    const csv = lines.map((fields) => fields.map(csvField).join(',') + '\n').join('');
    const url = URL.createObjectURL(new Blob([csv], { type: 'text/csv;charset=utf-8' }));
    const link = this.document.createElement('a');
    link.href = url;
    link.download = fileName;
    link.click();
    setTimeout(() => URL.revokeObjectURL(url));
  }

  protected gradeToday(p: Person): string {
    return gradeOn(p.grades, this.session.sheetToday());
  }

  /** The person's name as the screen shows it: with the grade in force on the sheet's today. */
  protected nameWithGrade(p: Person): string {
    return `${p.name} (${this.gradeToday(p)})`;
  }

  protected edit(p: Person): void {
    this.clearRowErrors(p.id);
    this.editingId.set(p.id);
    this.editingVersion.set(p.version);
    this.name.set(p.name);
    this.grade.set(this.gradeToday(p));
    this.gradeFrom.set('');
    this.terms.set(p.terms === null ? '' : String(p.terms));
